Method.Implementation:
Set tStatus = $$$OK, tConsumedJSON = ""
Do pOutput.SetAttribute("Content-Type","application/json")
Try {
Set tJSON = pInput.Read(32000) Set ^EAI.Debug("DeployPackage",1) = tJSON Do pInput.Rewind()
Set tConsumedJSON = ##class(%Library.DynamicAbstractObject).%FromJSON(pInput)
If ($$$IsdefObject(tConsumedJSON)) { Set tPackageName = tConsumedJSON.name Set tPackageDescription = tConsumedJSON.description Set tEnvironment = tConsumedJSON.environment Set tNamespace = tConsumedJSON.namespace Set tLDAPUsername = $System.Encryption.Base64Decode(tConsumedJSON.ldapUsername) Set tLDAPPassword = $System.Encryption.Base64Decode(tConsumedJSON.ldapPassword)
Set tPackage = ##class(IHC.EAI.Deployment.Package).%New() Set tPackage.Name = tPackageName Set tPackage.Description = tPackageDescription Set tPackage.Environment = tEnvironment Set tPackage.Namespace = tNamespace Set tPackage.LDAPUsername = tLDAPUsername Set tPackage.LDAPPassword = tLDAPPassword
Set tTargetProduction = ##class(IHC.EAI.Deployment.Util).GetTargetProduction(tNamespace,.tStatus) $$$ThrowOnError(tStatus)
Set tActionList = tConsumedJSON.actionList Set tIter = tActionList.%GetIterator() While (tIter.%GetNext(.key,.value)) { Set tType = value.type If (tType = "File") { Set tFilename = value.filename Set tComponentName = value.componentName Set tRevision = value.revision
Set tAction = ##class(IHC.EAI.Deployment.Action.File).%New() Set tAction.Filename = tFilename Set tAction.ComponentName = tComponentName Set tAction.Revision = tRevision Set tAction.TargetProduction = tTargetProduction Set tAction.CreateRollback = 1 Set tAction.RollbackFilename = $REPLACE(tFilename,".xml","_ROLLBACK.xml") Set tAction.WhereToLog = "L" Set tAction.LogFile = $REPLACE(tFilename,".xml",".log") Set tAction.AllowDeployToSource = 1 Set tAction.AutoRevert = 0
Set tStatus = tPackage.ActionList.Insert(tAction) $$$ThrowOnError(tStatus) } }
If (tPackage.ActionList.Count() > 0) { // Deploy the package Set tStatus = tPackage.Deploy() $$$ThrowOnError(tStatus)
//Set tMessage = tActionList.Count() Do pOutput.Write("{""success"": true,""message"":""Deployment package with " _ tPackage.ActionList.Count() _ " items successfully deployed.""}"_$C(13,10)) Quit } Do pOutput.Write("{""success"": true,""message"":""" _ tPackageName _ " did not deploy. No recognized actions were found.""}"_$C(13,10)) }
Do pOutput.Write("{""success"": true,""message"":""Nothing deployed, and no errors were record. Possible issue with inbound JSON structure.""}"_$C(13,10))
} Catch (eException) { Set tStatus = eException.AsStatus() Set tErrorMessage = $System.Status.GetErrorText(tStatus) Do pOutput.Write("{""success"": false,""message"":""" _ tErrorMessage _ """}"_$C(13,10)) }
Quit tStatus

Set tStatus = $$$OK Try {
Set tStatus = ..GetEnvironment(.tEnvironment,.tInstanceType,.tInstanceName) $$$ThrowOnError(tStatus)
// You could just write the output manually or use helper methods like ..ObjectToJSONStream() to generate JSON Do pOutput.SetAttribute("Content-Type","application/json") Do pOutput.Write("{")
Do pOutput.Write("""app"": {") Do pOutput.Write("""name"": ""EAI Deployment"",") Do pOutput.Write("""message"": ""Service is running"",") Do pOutput.Write("""environment"": """ _ tEnvironment _""",") Do pOutput.Write("""instanceType"": """ _ tInstanceType _""",") Do pOutput.Write("""InstanceName"": """ _ tInstanceName _""",") Do pOutput.Write("""message"": ""Service is running"",") Do pOutput.Write("""success"": true") Do pOutput.Write("}")
do pOutput.Write("}"_$C(13,10))
} Catch (eException) { Set tStatus = eException.AsStatus() }
Quit tStatus
